import{_ as e,o,c as d,a2 as a}from"./chunks/framework.BLx3XxyL.js";const l=JSON.parse('{"title":"Event Types Reference","description":"All Matrix state event types and message metadata types used by hookshot","frontmatter":{"title":"Event Types Reference","description":"All Matrix state event types and message metadata types used by hookshot","audience":["developer","contributor","architect"]},"headers":[],"relativePath":"reference/event-types.md","filePath":"reference/event-types.md","lastUpdated":1775244963000}'),r={name:"reference/event-types.md"};function s(i,t,h,n,c,u){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="event-types-reference" tabindex="-1">Event Types Reference <a class="header-anchor" href="#event-types-reference" aria-label="Permalink to &quot;Event Types Reference&quot;">​</a></h1><p>Hookshot uses custom Matrix state event types to store connection configuration and message metadata. All types follow the pattern <code>uk.half-shot.matrix-hookshot.{service}.{entity}</code> (with one exception for OpenProject).</p><h2 id="connection-state-event-types" tabindex="-1">Connection state event types <a class="header-anchor" href="#connection-state-event-types" aria-label="Permalink to &quot;Connection state event types&quot;">​</a></h2><p>These state events store connection configuration in Matrix rooms. Each connection instance is one state event.</p><table tabindex="0"><thead><tr><th>Event type</th><th>Connection class</th><th>Purpose</th></tr></thead><tbody><tr><td><code>uk.half-shot.matrix-hookshot.github.repository</code></td><td>GitHubRepoConnection</td><td>GitHub repo monitoring + commands</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.issue</code></td><td>GitHubIssueConnection</td><td>Single GitHub issue bridge</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.discussion</code></td><td>GitHubDiscussionConnection</td><td>GitHub discussion thread</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.discussion.space</code></td><td>GitHubDiscussionSpace</td><td>Space for repo discussions</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.project</code></td><td>GitHubProjectConnection</td><td>GitHub project board</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.user.space</code></td><td>GitHubUserSpace</td><td>User notification space</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.gitlab.repository</code></td><td>GitLabRepoConnection</td><td>GitLab project monitoring + commands</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.gitlab.issue</code></td><td>GitLabIssueConnection</td><td>Single GitLab issue bridge</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.jira.project</code></td><td>JiraProjectConnection</td><td>JIRA project monitoring + commands</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.generic.hook</code></td><td>GenericHookConnection</td><td>Inbound generic webhook</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.outbound-hook</code></td><td>OutboundHookConnection</td><td>Outbound message forwarding</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.feed</code></td><td>FeedConnection</td><td>RSS/Atom feed polling</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.figma.file</code></td><td>FigmaFileConnection</td><td>Figma file comment bridge</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.challengehound.activity</code></td><td>HoundConnection</td><td>ChallengeHound activity tracking</td></tr><tr><td><code>org.matrix.matrix-hookshot.openproject.project</code></td><td>OpenProjectConnection</td><td>OpenProject monitoring + commands</td></tr></tbody></table><p>The <strong>state key</strong> identifies the specific external resource (e.g., <code>my-org/my-repo</code> for a GitHub connection).</p><h2 id="message-metadata-event-types" tabindex="-1">Message metadata event types <a class="header-anchor" href="#message-metadata-event-types" aria-label="Permalink to &quot;Message metadata event types&quot;">​</a></h2><p>These types appear as custom fields inside <code>m.room.message</code> events to carry structured metadata about the source of the notification.</p><table tabindex="0"><thead><tr><th>Field name</th><th>Appears on</th><th>Content</th></tr></thead><tbody><tr><td><code>uk.half-shot.matrix-hookshot.github.repo</code></td><td>GitHub repo notifications</td><td><code>{ id, full_name, html_url, description }</code></td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.issue</code></td><td>GitHub issue notifications</td><td><code>{ id, number, title, html_url }</code></td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.pull_request</code></td><td>GitHub PR notifications</td><td><code>{ id, number, title, html_url }</code></td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.push</code></td><td>GitHub push notifications</td><td>Push event metadata</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.comment</code></td><td>GitHub comment notifications</td><td>Comment metadata</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.feeds.item</code></td><td>Feed entry notifications</td><td>Full feed entry object</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.jira.issue</code></td><td>JIRA issue notifications</td><td>Issue metadata</td></tr></tbody></table><h2 id="system-event-types" tabindex="-1">System event types <a class="header-anchor" href="#system-event-types" aria-label="Permalink to &quot;System event types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event type</th><th>Purpose</th><th>Stored in</th></tr></thead><tbody><tr><td><code>uk.half-shot.matrix-hookshot.github.room</code></td><td>Identifies admin room type</td><td>Room state</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.notif_state</code></td><td>GitHub notification filter</td><td>Room state</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.gitlab.notif_state</code></td><td>GitLab notification filter</td><td>Room state</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.figma.comment_id</code></td><td>Figma comment tracking</td><td>Room state</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.github.discussion.comment_id</code></td><td>Discussion comment tracking</td><td>Room state</td></tr><tr><td><code>uk.half-shot.matrix-hookshot.grant</code></td><td>OAuth grant tokens</td><td>Account data</td></tr><tr><td><code>org.matrix.matrix-hookshot.openproject.work_package</code></td><td>OpenProject work package tracking</td><td>Room state</td></tr></tbody></table><h2 id="legacy-event-types" tabindex="-1">Legacy event types <a class="header-anchor" href="#legacy-event-types" aria-label="Permalink to &quot;Legacy event types&quot;">​</a></h2><p>These event types were used in older versions and are still supported for backward compatibility. New connections use the current types above.</p><table tabindex="0"><thead><tr><th>Legacy type</th><th>Current type</th></tr></thead><tbody><tr><td><code>uk.half-shot.matrix-github.repository</code></td><td><code>uk.half-shot.matrix-hookshot.github.repository</code></td></tr><tr><td><code>uk.half-shot.matrix-github.bridge</code></td><td><code>uk.half-shot.matrix-hookshot.github.issue</code></td></tr><tr><td><code>uk.half-shot.matrix-github.discussion</code></td><td><code>uk.half-shot.matrix-hookshot.github.discussion</code></td></tr><tr><td><code>uk.half-shot.matrix-github.discussion.space</code></td><td><code>uk.half-shot.matrix-hookshot.github.discussion.space</code></td></tr><tr><td><code>uk.half-shot.matrix-github.project</code></td><td><code>uk.half-shot.matrix-hookshot.github.project</code></td></tr><tr><td><code>uk.half-shot.matrix-github.user.space</code></td><td><code>uk.half-shot.matrix-hookshot.github.user.space</code></td></tr><tr><td><code>uk.half-shot.matrix-github.notif_state</code></td><td><code>uk.half-shot.matrix-hookshot.github.notif_state</code></td></tr><tr><td><code>uk.half-shot.matrix-github.room</code></td><td><code>uk.half-shot.matrix-hookshot.github.room</code></td></tr><tr><td><code>uk.half-shot.matrix-github.generic.hook</code></td><td><code>uk.half-shot.matrix-hookshot.generic.hook</code></td></tr><tr><td><code>uk.half-shot.matrix-github.gitlab.repository</code></td><td><code>uk.half-shot.matrix-hookshot.gitlab.repository</code></td></tr><tr><td><code>uk.half-shot.matrix-github.gitlab.issue</code></td><td><code>uk.half-shot.matrix-hookshot.gitlab.issue</code></td></tr><tr><td><code>uk.half-shot.matrix-github.gitlab.notif_state</code></td><td><code>uk.half-shot.matrix-hookshot.gitlab.notif_state</code></td></tr><tr><td><code>uk.half-shot.matrix-github.jira.project</code></td><td><code>uk.half-shot.matrix-hookshot.jira.project</code></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Architecture:</strong> <a href="./../architecture/connections">Connections</a> — How connections use state events</p><p><strong>Integrations:</strong> <a href="./../integrations/overview">Overview</a> — All connection types</p><p><strong>Reference:</strong> <a href="./matrix-spec-map">Matrix Spec Map</a> · <a href="./bot-commands">Bot Commands</a></p><p><strong>Matrix Spec:</strong> <a href="https://spec.matrix.org/latest/client-server-api/#room-state" target="_blank" rel="noreferrer">Room State Events</a></p>',19)])])}const p=e(r,[["render",s]]);export{l as __pageData,p as default};
